package service;
import dao.support.ServiceFixture;import model.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class QueueServiceTest {
    private ServiceFixture store;private AuthService auth;private QueueService queue;private Session admin,student,officer;
    @BeforeEach void setup()throws Exception{store=new ServiceFixture();auth=new AuthService(store,12);queue=new QueueService(store,auth);admin=store.login(auth,Role.ADMIN);student=store.login(auth,Role.STUDENT);officer=store.login(auth,Role.OFFICER);store.locks.clear();}
    @Test void derivesStudentIdentityAndAcquiresOfficeBeforeStudentAndCounter()throws Exception{var ticket=queue.issue(student,1,"TEST-101",UUID.randomUUID());assertEquals(100,ticket.ticket().studentId());assertTrue(store.locks.indexOf("office:1")<store.locks.indexOf("student:100"));assertTrue(store.locks.indexOf("student:100")<store.locks.indexOf("counter"));assertEquals(4,store.actor);}
    @Test void blocksClosedOfficeAndWrongOfficeOfficer(){var old=store.offices.get(1L);store.offices.put(1L,new Organization(1,old.code(),old.name(),false,true,old.createdAt(),old.updatedAt()));assertThrows(ValidationException.class,()->queue.issue(student,1,null,UUID.randomUUID()));assertThrows(AuthorizationException.class,()->queue.issue(officer,2,"TEST-100",UUID.randomUUID()));}
    @Test void duplicateRequestReplaysButNewRequestCannotDuplicateActiveTicket()throws Exception{UUID key=UUID.randomUUID();var first=queue.issue(student,1,null,key);assertEquals(first,queue.issue(student,1,null,key));assertThrows(ValidationException.class,()->queue.issue(student,1,null,UUID.randomUUID()));assertEquals(1,store.sequence);}
    @Test void retriesOnlyConfirmedRollbackAndStopsAfterThreeAttempts()throws Exception{store.conflicts=2;int before=store.attempts;queue.issue(student,1,null,UUID.randomUUID());assertEquals(3,store.attempts-before);store.conflicts=4;before=store.attempts;assertThrows(TransactionConflictException.class,()->queue.issue(admin,1,"TEST-101",UUID.randomUUID()));assertEquals(3,store.attempts-before);}
    @Test void doesNotRetryAnUncertainCommitAndRecoversOriginal()throws Exception{UUID key=UUID.randomUUID();store.loseCommit=true;int before=store.attempts;assertThrows(CommitUncertainException.class,()->queue.issue(student,1,null,key));assertEquals(1,store.attempts-before);assertEquals(1,store.tickets.size());assertTrue(queue.recoverIssue(student,1,key).isPresent());assertThrows(AuthorizationException.class,()->queue.recoverIssue(admin,1,key));}
    @Test void fifoDeferAndRequeuePreserveNumber()throws Exception{var first=queue.issue(admin,1,"TEST-100",UUID.randomUUID());var second=queue.issue(admin,1,"TEST-101",UUID.randomUUID());var called=queue.callNext(officer,1).orElseThrow();assertEquals(first.ticket().id(),called.ticket().id());assertThrows(ValidationException.class,()->queue.callNext(officer,1));var deferred=queue.transition(officer,called,QueueAction.DEFER,null);var requeued=queue.transition(student,deferred,QueueAction.REQUEUE,null);assertEquals(first.number(),requeued.number());assertNull(requeued.ticket().calledAt());assertEquals(second.ticket().id(),queue.callNext(officer,1).orElseThrow().ticket().id());}
    @Test void rejectsStaleSelectionAndStudentServingActions()throws Exception{var first=queue.issue(student,1,null,UUID.randomUUID());var called=queue.callNext(officer,1).orElseThrow();assertThrows(RecordChangedException.class,()->queue.transition(officer,first,QueueAction.DEFER,null));assertThrows(AuthorizationException.class,()->queue.transition(student,called,QueueAction.START_SERVING,null));}
    @Test void requiresCurrentTermAndCancellationReason()throws Exception{store.termPresent=false;assertThrows(ValidationException.class,()->queue.issue(student,1,null,UUID.randomUUID()));store.termPresent=true;var ticket=queue.issue(student,1,null,UUID.randomUUID());assertThrows(ValidationException.class,()->queue.transition(student,ticket,QueueAction.CANCEL," "));}
}
